import { K as GRAY, L as ERODE, M as DILATE, Mt as POSTERIZE, d as BLUR, sn as THRESHOLD, tt as INVERT, xt as OPAQUE } from "../constants-DA50zLWL.js";
//#region src/core/filterShaders.js
function makeFilterShader(renderer, operation, p5) {
	switch (operation) {
		case GRAY: return renderer.baseFilterShader().modify(({ p5 }) => {
			p5.getColor((inputs, canvasContent) => {
				const tex = p5.getTexture(canvasContent, inputs.texCoord);
				const gray = p5.dot(tex.rgb, p5.vec3(.2126, .7152, .0722));
				return p5.vec4(gray, gray, gray, tex.a);
			});
		}, { p5 });
		case INVERT: return renderer.baseFilterShader().modify(({ p5 }) => {
			p5.getColor((inputs, canvasContent) => {
				const color = p5.getTexture(canvasContent, inputs.texCoord);
				const invertedColor = p5.vec3(1) - color.rgb;
				return p5.vec4(invertedColor, color.a);
			});
		}, { p5 });
		case THRESHOLD: return renderer.baseFilterShader().modify(({ p5 }) => {
			const filterParameter = p5.uniformFloat("filterParameter");
			p5.getColor((inputs, canvasContent) => {
				const color = p5.getTexture(canvasContent, inputs.texCoord);
				const gray = p5.dot(color.rgb, p5.vec3(.2126, .7152, .0722));
				const threshold = p5.floor(filterParameter * 255) / 255;
				const blackOrWhite = p5.step(threshold, gray);
				return p5.vec4(p5.vec3(blackOrWhite), color.a);
			});
		}, { p5 });
		case POSTERIZE: return renderer.baseFilterShader().modify(({ p5 }) => {
			const filterParameter = p5.uniformFloat("filterParameter");
			const quantize = (color, n) => {
				color = color * n;
				color = p5.floor(color);
				color = color / (n - 1);
				return color;
			};
			p5.getColor((inputs, canvasContent) => {
				const color = p5.getTexture(canvasContent, inputs.texCoord);
				const restrictedColor = quantize(color.rgb, filterParameter);
				return p5.vec4(restrictedColor, color.a);
			});
		}, { p5 });
		case BLUR: return renderer.baseFilterShader().modify(({ p5 }) => {
			const radius = p5.uniformFloat("radius");
			const direction = p5.uniformVec2("direction");
			const quadWeight = (x, e) => {
				return p5.pow(e - p5.abs(x), 2);
			};
			const random = (p) => {
				let p3 = p5.fract(p.xyx * .1031);
				p3 += p5.dot(p3, p3.yzx + 33.33);
				return p5.fract((p3.x + p3.y) * p3.z);
			};
			p5.getColor((inputs, canvasContent) => {
				const uv = inputs.texCoord;
				const maxSamples = 64;
				let numSamples = p5.floor(radius * 7);
				if (p5.mod(numSamples, 2) === 0) numSamples++;
				let avg = p5.vec4(0);
				let total = 0;
				let spacing = 1;
				if (numSamples > maxSamples) {
					spacing = numSamples / maxSamples;
					numSamples = maxSamples;
				}
				const devicePixel = inputs.texelSize.x * inputs.canvasSize.x;
				const randomOffset = p5.max(spacing - devicePixel, 0) * p5.mix(-.5, .5, random(uv * inputs.canvasSize));
				for (let i = 0; i < numSamples; i++) {
					const sample = i * spacing - (numSamples - 1) * .5 * spacing + randomOffset;
					const sampleCoord = uv + p5.vec2(sample, sample) / inputs.canvasSize * direction;
					const weight = quadWeight(sample, (numSamples - 1) * .5 * spacing);
					const texSample = p5.getTexture(canvasContent, sampleCoord);
					avg += weight * texSample * p5.vec4(texSample.a, texSample.a, texSample.a, 1);
					total += weight;
				}
				const blended = avg / total;
				return p5.vec4(blended.r / blended.a, blended.g / blended.a, blended.b / blended.a, blended.a);
			});
		}, { p5 });
		case ERODE: return renderer.baseFilterShader().modify(({ p5 }) => {
			const luma = (color) => {
				return p5.dot(color.rgb, p5.vec3(.2126, .7152, .0722));
			};
			p5.getColor((inputs, canvasContent) => {
				const uv = inputs.texCoord;
				let minColor = p5.getTexture(canvasContent, uv);
				let minLuma = luma(minColor);
				for (let x = -1; x <= 1; x++) for (let y = -1; y <= 1; y++) if (x !== 0 || y !== 0) {
					const offset = p5.vec2(x, y) * inputs.texelSize;
					const neighborColor = p5.getTexture(canvasContent, uv + offset);
					const neighborLuma = luma(neighborColor);
					if (neighborLuma < minLuma) {
						minLuma = neighborLuma;
						minColor = neighborColor;
					}
				}
				return minColor;
			});
		}, { p5 });
		case DILATE: return renderer.baseFilterShader().modify(({ p5 }) => {
			const luma = (color) => {
				return p5.dot(color.rgb, p5.vec3(.2126, .7152, .0722));
			};
			p5.getColor((inputs, canvasContent) => {
				const uv = inputs.texCoord;
				let maxColor = p5.getTexture(canvasContent, uv);
				let maxLuma = luma(maxColor);
				for (let x = -1; x <= 1; x++) for (let y = -1; y <= 1; y++) if (x !== 0 || y !== 0) {
					const offset = p5.vec2(x, y) * inputs.texelSize;
					const neighborColor = p5.getTexture(canvasContent, uv + offset);
					const neighborLuma = luma(neighborColor);
					if (neighborLuma > maxLuma) {
						maxLuma = neighborLuma;
						maxColor = neighborColor;
					}
				}
				return maxColor;
			});
		}, { p5 });
		case OPAQUE: return renderer.baseFilterShader().modify(({ p5 }) => {
			p5.getColor((inputs, canvasContent) => {
				const color = p5.getTexture(canvasContent, inputs.texCoord);
				return p5.vec4(color.rgb, 1);
			});
		}, { p5 });
		default: throw new Error(`Unknown filter: ${operation}`);
	}
}
//#endregion
export { makeFilterShader };
