import { ColorSpace, sRGB } from "colorjs.io/fn";
//#region src/color/color_spaces/hsb.js
var hsb_default = new ColorSpace({
	id: "hsb",
	name: "HSB",
	coords: {
		h: {
			refRange: [0, 360],
			type: "angle",
			name: "Hue"
		},
		s: {
			range: [0, 100],
			name: "Saturation"
		},
		b: {
			range: [0, 100],
			name: "Brightness"
		}
	},
	base: sRGB,
	fromBase: (rgb) => {
		const val = Math.max(...rgb);
		const chroma = val - Math.min(...rgb);
		let [red, green, blue] = rgb;
		let hue, sat;
		if (chroma === 0) {
			hue = 0;
			sat = 0;
		} else {
			sat = chroma / val;
			if (red === val) hue = (green - blue) / chroma;
			else if (green === val) hue = 2 + (blue - red) / chroma;
			else if (blue === val) hue = 4 + (red - green) / chroma;
			if (hue < 0) hue += 6;
			else if (hue >= 6) hue -= 6;
		}
		return [
			hue / 6 * 360,
			sat * 100,
			val * 100
		];
	},
	toBase,
	formats: {
		default: {
			type: "custom",
			serialize: (coords, alpha) => {
				const rgb = toBase(coords);
				let ret = `rgb(${Math.round(rgb[0] * 100 * 100) / 100}% ${Math.round(rgb[1] * 100 * 100) / 100}% ${Math.round(rgb[2] * 100 * 100) / 100}%`;
				if (alpha < 1) ret += ` / ${alpha}`;
				ret += ")";
				return ret;
			}
		},
		hsb: { coords: [
			"<number> | <angle>",
			"<percentage>",
			"<percentage>"
		] },
		hsba: {
			coords: [
				"<number> | <angle>",
				"<percentage>",
				"<percentage>"
			],
			commans: true,
			lastAlpha: true
		}
	}
});
function toBase(hsb) {
	const hue = hsb[0] / 360 * 6;
	const sat = hsb[1] / 100;
	const val = hsb[2] / 100;
	let RGB = [];
	if (sat === 0) RGB = [
		val,
		val,
		val
	];
	else {
		const sector = Math.floor(hue);
		const tint1 = val * (1 - sat);
		const tint2 = val * (1 - sat * (hue - sector));
		const tint3 = val * (1 - sat * (1 + sector - hue));
		let red, green, blue;
		if (sector === 1) {
			red = tint2;
			green = val;
			blue = tint1;
		} else if (sector === 2) {
			red = tint1;
			green = val;
			blue = tint3;
		} else if (sector === 3) {
			red = tint1;
			green = tint2;
			blue = val;
		} else if (sector === 4) {
			red = tint3;
			green = tint1;
			blue = val;
		} else if (sector === 5) {
			red = val;
			green = tint1;
			blue = tint2;
		} else {
			red = val;
			green = tint3;
			blue = tint1;
		}
		RGB = [
			red,
			green,
			blue
		];
	}
	return RGB;
}
//#endregion
export { hsb_default as default };
